#### Implementation Pattern 1: Application-Level Router

**Concept**: Query router implemented as library/middleware in application code

**Example - Node.js Query Router**:

```typescript
// shard-router.ts
import { Pool } from 'pg';
import { ShardMappingService } from './shard-mapping-service';

export interface ShardConfig {
  shardId: string;
  partitionKeys: string[];
  connectionString: string;
  region: string;
}

export interface QueryContext {
  partitionKey?: string;  // Single partition key (e.g., 'FL')
  allPartitions?: boolean; // Query all partitions
}

export class ShardRouter {
  private shards: Map<string, Pool> = new Map();
  private partitionKeyToShard: Map<string, string> = new Map();
  private shardMappingService: ShardMappingService;

  constructor(shardConfigs: ShardConfig[], shardMappingService: ShardMappingService) {
    this.shardMappingService = shardMappingService;
    this.initializeShards(shardConfigs);
  }

  private initializeShards(configs: ShardConfig[]): void {
    for (const config of configs) {
      // Create connection pool for each shard
      const pool = new Pool({
        connectionString: config.connectionString,
        max: 20, // Connection pool size
        idleTimeoutMillis: 30000,
        connectionTimeoutMillis: 5000,
      });

      this.shards.set(config.shardId, pool);

      // Map partition keys to shard ID
      for (const partitionKey of config.partitionKeys) {
        this.partitionKeyToShard.set(partitionKey, config.shardId);
      }
    }
  }

  /**
   * Route query to appropriate shard(s)
   */
  async query<T>(
    sql: string,
    params: any[],
    context: QueryContext
  ): Promise<T[]> {
    if (context.allPartitions) {
      return this.queryAllShards<T>(sql, params);
    } else if (context.partitionKey) {
      return this.querySingleShard<T>(sql, params, context.partitionKey);
    } else {
      throw new Error('QueryContext must specify partitionKey or allPartitions=true');
    }
  }

  /**
   * Query single partition
   */
  private async querySingleShard<T>(
    sql: string,
    params: any[],
    partitionKey: string
  ): Promise<T[]> {
    const shardId = this.partitionKeyToShard.get(partitionKey);
    if (!shardId) {
      throw new Error(`No shard found for partition key: ${partitionKey}`);
    }

    const pool = this.shards.get(shardId);
    if (!pool) {
      throw new Error(`Shard pool not initialized: ${shardId}`);
    }

    const startTime = Date.now();
    try {
      const result = await pool.query(sql, params);
      const duration = Date.now() - startTime;

      // Metrics
      this.recordMetrics('single_shard_query', {
        shard_id: shardId,
        partition_key: partitionKey,
        duration_ms: duration,
        row_count: result.rows.length,
      });

      return result.rows as T[];
    } catch (error) {
      this.recordError('single_shard_query_error', {
        shard_id: shardId,
        partition_key: partitionKey,
        error: error.message,
      });
      throw error;
    }
  }

  /**
   * Query all partitions and aggregate results
   */
  private async queryAllShards<T>(sql: string, params: any[]): Promise<T[]> {
    const startTime = Date.now();
    const shardIds = Array.from(this.shards.keys());

    try {
      // Execute query on all shards in parallel
      const promises = shardIds.map(async (shardId) => {
        const pool = this.shards.get(shardId);
        const result = await pool.query(sql, params);
        return {
          shardId,
          rows: result.rows as T[],
        };
      });

      const results = await Promise.all(promises);

      // Aggregate results from all shards
      const aggregatedRows = results.flatMap(r => r.rows);
      const duration = Date.now() - startTime;

      this.recordMetrics('cross_shard_query', {
        shard_count: shardIds.length,
        duration_ms: duration,
        total_row_count: aggregatedRows.length,
      });

      return aggregatedRows;
    } catch (error) {
      this.recordError('cross_shard_query_error', {
        shard_count: shardIds.length,
        error: error.message,
      });
      throw error;
    }
  }

  /**
   * Execute transaction within single partition
   */
  async transaction<T>(
    partitionKey: string,
    callback: (client: any) => Promise<T>
  ): Promise<T> {
    const shardId = this.partitionKeyToShard.get(partitionKey);
    if (!shardId) {
      throw new Error(`No shard found for partition key: ${partitionKey}`);
    }

    const pool = this.shards.get(shardId);
    const client = await pool.connect();

    try {
      await client.query('BEGIN');
      const result = await callback(client);
      await client.query('COMMIT');
      return result;
    } catch (error) {
      await client.query('ROLLBACK');
      throw error;
    } finally {
      client.release();
    }
  }

  private recordMetrics(metric: string, tags: Record<string, any>): void {
    // Send to Prometheus, Application Insights, etc.
    console.log(`Metric: ${metric}`, tags);
  }

  private recordError(error: string, tags: Record<string, any>): void {
    // Send to error tracking (Sentry, Application Insights)
    console.error(`Error: ${error}`, tags);
  }

  async close(): Promise<void> {
    const promises = Array.from(this.shards.values()).map(pool => pool.end());
    await Promise.all(promises);
  }
}
```

**Usage Example**:

```typescript
// claims-service.ts
import { ShardRouter, QueryContext } from './shard-router';

export class ClaimsService {
  constructor(private shardRouter: ShardRouter) {}

  /**
   * Get claims for member (single partition)
   */
  async getClaimsByMember(stateCode: string, memberId: string): Promise<Claim[]> {
    const sql = `
      SELECT claim_id, member_id, service_date, provider_id, amount, status
      FROM claims
      ORDER BY service_date DESC
      LIMIT 50
    `;

    const context: QueryContext = { partitionKey: stateCode };
    const claims = await this.shardRouter.query<Claim>(sql, [memberId], context);
    return claims;
  }

  /**
   * Get claims summary across all states (cross-partition)
   */
  async getClaimsSummaryAllStates(): Promise<ClaimsSummary> {
    const sql = `
      SELECT
        COUNT(*) as total_claims,
        SUM(amount) as total_amount,
        AVG(amount) as avg_amount
      FROM claims
      WHERE service_date >= CURRENT_DATE - INTERVAL '30 days'
    `;

    const context: QueryContext = { allPartitions: true };
    const results = await this.shardRouter.query<any>(sql, [], context);

    // Aggregate results from all shards
    const summary = results.reduce((acc, row) => ({
      total_claims: acc.total_claims + parseInt(row.total_claims),
      total_amount: acc.total_amount + parseFloat(row.total_amount),
      avg_amount: 0, // Recalculate after aggregation
    }), { total_claims: 0, total_amount: 0, avg_amount: 0 });

    summary.avg_amount = summary.total_amount / summary.total_claims;
    return summary;
  }

  /**
   * Create claim (single partition transaction)
   */
  async createClaim(stateCode: string, claim: ClaimInput): Promise<Claim> {
    return this.shardRouter.transaction(stateCode, async (client) => {
      // Insert claim
      const claimResult = await client.query(
        [claim.memberId, claim.serviceDate, claim.providerId, claim.amount]
      );

      // Insert claim lines (same transaction, same partition)
      for (const line of claim.lines) {
        await client.query(
          [claimResult.rows[0].claim_id, line.lineNumber, line.cptCode, line.amount]
        );
      }

      return claimResult.rows[0];
    });
  }
}
```

