#### Implementation - Redis-Based Mapping Service

```typescript
// shard-mapping-service.ts
import Redis from 'ioredis';

export interface ShardMapping {
  shardId: string;
  partitionKeys: string[];
  connectionString: string;
  readonlyConnectionString?: string;
  region: string;
  status: 'active' | 'draining' | 'readonly';
}

export class ShardMappingService {
  private redis: Redis;
  private cacheKey = 'shard_mappings:v3';
  private cacheTTL = 300; // 5 minutes

  constructor(redisUrl: string) {
    this.redis = new Redis(redisUrl);
  }

  /**
   * Get shard for partition key
   */
  async getShard(partitionKey: string): Promise<ShardMapping | null> {
    const mappings = await this.getAllMappings();

    for (const shard of mappings) {
      if (shard.partitionKeys.includes(partitionKey)) {
        return shard;
      }
    }

    return null;
  }

  /**
   * Get all shard mappings (cached)
   */
  async getAllMappings(): Promise<ShardMapping[]> {
    // Try cache first
    const cached = await this.redis.get(this.cacheKey);
    if (cached) {
      return JSON.parse(cached);
    }

    // Fetch from source (configuration service, database, etc.)
    const mappings = await this.fetchMappingsFromSource();

    // Cache for TTL
    await this.redis.setex(this.cacheKey, this.cacheTTL, JSON.stringify(mappings));

    return mappings;
  }

  /**
   * Update shard mapping (e.g., during rebalancing)
   */
  async updateMapping(mapping: ShardMapping): Promise<void> {
    const mappings = await this.getAllMappings();

    const index = mappings.findIndex(m => m.shardId === mapping.shardId);
    if (index >= 0) {
      mappings[index] = mapping;
    } else {
      mappings.push(mapping);
    }

    // Update cache
    await this.redis.setex(this.cacheKey, this.cacheTTL, JSON.stringify(mappings));

    // Publish update event (for invalidating caches across services)
    await this.redis.publish('shard_mapping_updated', JSON.stringify(mapping));
  }

  private async fetchMappingsFromSource(): Promise<ShardMapping[]> {
    // In production: Fetch from configuration service, Azure App Configuration, etc.
    // For now, return hardcoded mappings
    return [
      {
        shardId: 'FL',
        partitionKeys: ['FL'],
        connectionString: process.env.DB_FL_CONNECTION_STRING,
        readonlyConnectionString: process.env.DB_FL_READONLY_CONNECTION_STRING,
        region: 'eastus',
        status: 'active',
      },
      {
        shardId: 'CA',
        partitionKeys: ['CA'],
        connectionString: process.env.DB_CA_CONNECTION_STRING,
        readonlyConnectionString: process.env.DB_CA_READONLY_CONNECTION_STRING,
        region: 'westus',
        status: 'active',
      },
      // ... other shards
    ];
  }
}
```

