#### Phase 3: Implement Query Router (2-3 weeks)

**Step 3.1: Implement Shard Mapping Service**

See "Query Router Implementation" section above for full code examples.

**Step 3.2: Implement Application-Level Router**

```typescript
// Initialize router at application startup
import { ShardRouter } from './shard-router';
import { ShardMappingService } from './shard-mapping-service';

const shardConfigs = await loadShardConfigsFromKeyVault();
const mappingService = new ShardMappingService(process.env.REDIS_URL);
const shardRouter = new ShardRouter(shardConfigs, mappingService);

// Inject router into services
const claimsService = new ClaimsService(shardRouter);
const membersService = new MembersService(shardRouter);
```

**Step 3.3: Extract Partition Key from Request Context**

```typescript
// Middleware to extract partition key from request
export function extractPartitionKey(req: Request, res: Response, next: NextFunction) {
  // Option 1: From URL path parameter
  // GET /api/states/FL/claims
  const stateCode = req.params.stateCode;

  // Option 2: From query parameter
  // GET /api/claims?state_code=FL
  const stateCodeQuery = req.query.state_code;

  // Option 3: From authenticated user context (JWT token)
  const user = req.user as AuthenticatedUser;
  const userStateCode = user.stateCode;  // User assigned to specific state

  // Store in request context
  req.partitionKey = stateCode || stateCodeQuery || userStateCode;

  if (!req.partitionKey) {
    return res.status(400).json({ error: 'state_code required' });
  }

  next();
}

// Apply middleware to routes
app.use('/api/claims', extractPartitionKey);
app.use('/api/members', extractPartitionKey);
```

**Step 3.4: Update Service Methods to Use Router**

```typescript
// Before (direct database access):
async getClaimsByMember(memberId: string): Promise<Claim[]> {
}

// After (routed via partition key):
async getClaimsByMember(stateCode: string, memberId: string): Promise<Claim[]> {
  const context: QueryContext = { partitionKey: stateCode };
  return this.shardRouter.query<Claim>(
    [memberId],
    context
  );
}
```

