#### Phase 4: Data Migration (4-8 weeks, depending on data volume)

**Approach**: Dual-write strategy (minimize downtime)

**Migration Steps**:

1. **Enable Dual-Write** (write to both old database and new partitions)
2. **Backfill Historical Data** (copy existing data to partitions)
3. **Verify Data Consistency** (compare old vs. new)
4. **Switch Reads to Partitions** (start querying partitions)
5. **Disable Dual-Write** (write only to partitions)
6. **Decommission Old Database** (after soak period)

**Step 4.1: Implement Dual-Write**

```typescript
// Claims Service - Dual-write during migration
export class ClaimsService {
  private migrationMode: boolean = true;  // Feature flag

  async createClaim(stateCode: string, claim: ClaimInput): Promise<Claim> {
    // Write to new partitioned database
    const newClaim = await this.shardRouter.transaction(stateCode, async (client) => {
      const result = await client.query(
        [claim.memberId, stateCode, claim.serviceDate, claim.amount]
      );
      return result.rows[0];
    });

    // Also write to old monolithic database (during migration)
    if (this.migrationMode) {
      try {
        await this.oldDatabase.query(
          [newClaim.claim_id, claim.memberId, stateCode, claim.serviceDate, claim.amount]
        );
      } catch (error) {
        // Log error but don't fail request (new partition is source of truth)
        logger.error('Dual-write to old database failed', { error, claim_id: newClaim.claim_id });
      }
    }

    return newClaim;
  }
}
```

**Step 4.2: Backfill Historical Data**

```typescript
// backfill-partition.ts
// Run as background job for each partition

interface BackfillOptions {
  partitionKey: string;
  batchSize: number;
  throttleMs: number;  // Delay between batches
}

async function backfillPartition(options: BackfillOptions): Promise<void> {
  const { partitionKey, batchSize, throttleMs } = options;

  let offset = 0;
  let processedCount = 0;

  while (true) {
    // Fetch batch from old database
    const batch = await oldDatabase.query(
      [partitionKey, batchSize, offset]
    );

    if (batch.rows.length === 0) break;  // No more data

    // Insert batch into new partition
    const shard = await shardMappingService.getShard(partitionKey);
    const pool = new Pool({ connectionString: shard.connectionString });

    for (const row of batch.rows) {
      await pool.query(
        [row.claim_id, row.member_id, row.state_code, row.service_date, row.provider_id, row.amount, row.status]
      );
    }

    processedCount += batch.rows.length;
    offset += batchSize;

    logger.info(`Backfilled partition ${partitionKey}`, { processed: processedCount, offset });

    // Throttle to avoid overwhelming database
    await new Promise(resolve => setTimeout(resolve, throttleMs));
  }

  logger.info(`Backfill complete for partition ${partitionKey}`, { total_records: processedCount });
}

// Run backfill for each partition (parallelized)
const partitions = ['FL', 'CA', 'TX', /* ... */];
await Promise.all(
  partitions.map(pk => backfillPartition({ partitionKey: pk, batchSize: 10000, throttleMs: 100 }))
);
```

**Performance**: 10,000 records/batch, 100ms throttle = 100K records/second per partition
- Florida (58M claims): ~10 minutes
- Total (480M claims across 50 partitions): ~80 minutes (parallelized)

**Step 4.3: Verify Data Consistency**

```typescript
// verify-migration.ts
// Compare record counts, checksums between old database and new partitions

async function verifyPartition(partitionKey: string): Promise<boolean> {
  // Count records in old database
  const oldCount = await oldDatabase.query(
    [partitionKey]
  );

  // Count records in new partition
  const context: QueryContext = { partitionKey };
  const newCount = await shardRouter.query<{count: string}>(
    'SELECT COUNT(*) as count FROM claims',
    [],
    context
  );

  const oldTotal = parseInt(oldCount.rows[0].count);
  const newTotal = parseInt(newCount[0].count);

  if (oldTotal !== newTotal) {
    logger.error(`Migration verification failed for partition ${partitionKey}`, {
      old_count: oldTotal,
      new_count: newTotal,
      difference: oldTotal - newTotal,
    });
    return false;
  }

  // Checksum verification (sample 1% of records)
  const sampleSize = Math.floor(oldTotal * 0.01);
  const oldSample = await oldDatabase.query(
    [partitionKey, sampleSize]
  );

  for (const oldRow of oldSample.rows) {
    const newRow = await shardRouter.query<Claim>(
      [oldRow.claim_id],
      context
    );

    if (!newRow || newRow.length === 0) {
      logger.error(`Missing claim in new partition`, { partition: partitionKey, claim_id: oldRow.claim_id });
      return false;
    }

    // Verify key fields match
    if (newRow[0].amount !== oldRow.amount || newRow[0].status !== oldRow.status) {
      logger.error(`Data mismatch`, {
        partition: partitionKey,
        claim_id: oldRow.claim_id,
        old: oldRow,
        new: newRow[0],
      });
      return false;
    }
  }

  logger.info(`Migration verified for partition ${partitionKey}`, {
    total_count: oldTotal,
    sample_verified: sampleSize,
  });
  return true;
}
```

**Step 4.4: Switch Reads to Partitions**

```typescript
// Feature flag to gradually shift read traffic
const READ_FROM_PARTITIONS_PERCENTAGE = 100;  // 0-100

async function getClaimsByMember(stateCode: string, memberId: string): Promise<Claim[]> {
  const usePartitions = Math.random() * 100 < READ_FROM_PARTITIONS_PERCENTAGE;

  if (usePartitions) {
    // Query new partitioned database
    const context: QueryContext = { partitionKey: stateCode };
    return this.shardRouter.query<Claim>(
      [memberId],
      context
    );
  } else {
    // Query old monolithic database (fallback)
    return this.oldDatabase.query(
      [stateCode, memberId]
    );
  }
}

// Gradual rollout:
// Day 1: 10% read from partitions
// Day 2: 25%
// Day 3: 50%
// Day 4: 75%
// Day 5: 100% (if no issues)
```

