#### Phase 5: Monitoring and Operations (Ongoing)

**Step 5.1: Implement Partition Health Monitoring**

```typescript
// Prometheus metrics
import { Counter, Histogram, Gauge } from 'prom-client';

const queryDurationHistogram = new Histogram({
  name: 'shard_query_duration_seconds',
  help: 'Query duration by shard',
  labelNames: ['shard_id', 'query_type', 'partition_key'],
  buckets: [0.01, 0.05, 0.1, 0.5, 1, 2, 5],
});

const queryErrorCounter = new Counter({
  name: 'shard_query_errors_total',
  help: 'Query errors by shard',
  labelNames: ['shard_id', 'partition_key', 'error_type'],
});

const partitionSizeGauge = new Gauge({
  name: 'shard_size_bytes',
  help: 'Partition database size in bytes',
  labelNames: ['shard_id'],
});

const partitionUtilizationGauge = new Gauge({
  name: 'shard_utilization_percent',
  help: 'Partition capacity utilization',
  labelNames: ['shard_id'],
});

// Record metrics in query router
private recordMetrics(metric: string, tags: Record<string, any>): void {
  if (metric === 'single_shard_query') {
    queryDurationHistogram.labels(tags.shard_id, 'single', tags.partition_key)
      .observe(tags.duration_ms / 1000);
  }
}
```

**Step 5.2: Configure Alerting**

```yaml
# Prometheus alerting rules
groups:

  - name: shard_health
    interval: 30s
    rules:
      - alert: ShardHighLatency
        expr: histogram_quantile(0.95, rate(shard_query_duration_seconds_bucket[5m])) > 2
        for: 5m
        labels:
          severity: warning
        annotations:
          summary: "Shard {{ $labels.shard_id }} has high query latency"
          description: "P95 latency is {{ $value }}s (threshold: 2s)"

      - alert: ShardConnectionPoolExhausted
        expr: rate(shard_connection_pool_exhausted_total[5m]) > 10
        for: 2m
        labels:
          severity: critical
        annotations:
          summary: "Shard {{ $labels.shard_id }} connection pool exhausted"

      - alert: ShardUtilizationHigh
        expr: shard_utilization_percent > 85
        for: 1h
        labels:
          severity: warning
        annotations:
          summary: "Shard {{ $labels.shard_id }} utilization high"
          description: "Utilization at {{ $value }}% (threshold: 85%). Consider rebalancing."

      - alert: CrossShardQueryRateHigh
        expr: rate(shard_query_duration_seconds_count{query_type="cross_shard"}[5m]) > 100
        for: 10m
        labels:
          severity: warning
        annotations:
          summary: "High rate of cross-shard queries"
          description: "{{ $value }} cross-shard queries/sec. Consider adding read models or caching."
```

**Step 5.3: Implement Automated Rebalancing**

```typescript
// rebalancing-job.ts
// Runs weekly to check for partition imbalances

interface RebalancingPlan {
  sourceShardId: string;
  targetShardId: string;
  partitionKeys: string[];
  estimatedRecords: number;
}

async function analyzePartitionBalance(): Promise<RebalancingPlan[]> {
  const shards = await shardMappingService.getAllMappings();
  const plans: RebalancingPlan[] = [];

  for (const shard of shards) {
    // Query partition utilization
    const pool = new Pool({ connectionString: shard.connectionString });
    const result = await pool.query(`
      SELECT
        pg_database_size(current_database()) as size_bytes,
        (SELECT COUNT(*) FROM claims) as record_count
    `);

    const utilization = (result.rows[0].size_bytes / shard.capacity.max_size_bytes) * 100;

    if (utilization > 85) {
      // Find underutilized shard to move partition keys to
      const targetShard = shards.find(s => {
        const targetUtil = (s.current_size_bytes / s.capacity.max_size_bytes) * 100;
        return targetUtil < 60 && s.region === shard.region;
      });

      if (targetShard) {
        // Identify partition keys to move (smallest states first)
        const smallestKeys = shard.partitionKeys
          .slice(0, Math.floor(shard.partitionKeys.length * 0.2));  // Move 20% of partition keys

        plans.push({
          sourceShardId: shard.shardId,
          targetShardId: targetShard.shardId,
          partitionKeys: smallestKeys,
          estimatedRecords: result.rows[0].record_count * 0.2,
        });
      }
    }
  }

  return plans;
}

// Execute rebalancing plan (manual approval required)
async function executeRebalancingPlan(plan: RebalancingPlan): Promise<void> {
  logger.info('Starting rebalancing', plan);

  for (const partitionKey of plan.partitionKeys) {
    // Step 1: Copy data to target shard (same as backfill process)
    await backfillPartition({
      partitionKey,
      sourceShard: plan.sourceShardId,
      targetShard: plan.targetShardId,
      batchSize: 10000,
      throttleMs: 100,
    });

    // Step 2: Enable dual-write to both shards
    await shardMappingService.updateMapping({
      partitionKey,
      primaryShard: plan.targetShardId,
      secondaryShard: plan.sourceShardId,  // Keep writing to old shard temporarily
    });

    // Step 3: Wait for replication lag to stabilize (2 hours)
    await new Promise(resolve => setTimeout(resolve, 2 * 60 * 60 * 1000));

    // Step 4: Switch reads to target shard
    await shardMappingService.updateMapping({
      partitionKey,
      primaryShard: plan.targetShardId,
      secondaryShard: null,  // Stop dual-write
    });

    // Step 5: Delete data from source shard (after soak period)
    // (Manual step, requires approval)
  }

  logger.info('Rebalancing complete', plan);
}
```

