#### Data Quality Governance

**Challenge**: Data quality issues in one partition (e.g., Florida) shouldn't propagate to other partitions.

**Data Quality Framework**:

```yaml
data_quality_rules:
  # Partition-level rules (enforced at database layer)
  partition_isolation:
    - rule: "Member state_code must match partition key"
      enforcement: database_constraint
      example: "FL partition can only contain state_code='FL' members"

    - rule: "Cross-partition foreign keys prohibited"
      enforcement: application_validation
      example: "FL claim cannot reference CA member"

  # Per-partition data quality metrics
  quality_metrics:
    - metric: member_data_completeness
      definition: "% of members with all required fields populated"
      target: 99.5%
      measured_per_partition: true
      alert_threshold: 98%

    - metric: claim_adjudication_accuracy
      definition: "% of claims adjudicated correctly (no reprocessing)"
      target: 99.9%
      measured_per_partition: true
      alert_threshold: 99.5%
```

**Data Quality Monitoring (Partition-Specific)**:

```typescript
// Data quality check - per partition
async function checkPartitionDataQuality(partitionKey: string): Promise<DataQualityReport> {
  const context: QueryContext = { partitionKey };

  // Check 1: Partition key consistency
  const inconsistentRecords = await shardRouter.query<any>(
    [partitionKey],
    context
  );

  // Check 2: Data completeness
  const incompleteMembers = await shardRouter.query<any>(
    `SELECT COUNT(*) as count FROM members
     WHERE first_name IS NULL OR last_name IS NULL OR date_of_birth IS NULL`,
    [],
    context
  );

  // Check 3: Orphaned records (claims without members)
  const orphanedClaims = await shardRouter.query<any>(
    `SELECT COUNT(*) as count FROM claims c
     WHERE NOT EXISTS (SELECT 1 FROM members m WHERE m.member_id = c.member_id)`,
    [],
    context
  );

  return {
    partition_key: partitionKey,
    inconsistent_records: inconsistentRecords[0].count,
    incomplete_members: incompleteMembers[0].count,
    orphaned_claims: orphanedClaims[0].count,
    quality_score: calculateQualityScore({
      inconsistent_records: inconsistentRecords[0].count,
      incomplete_members: incompleteMembers[0].count,
      orphaned_claims: orphanedClaims[0].count,
    }),
  };
}

// Run daily for each partition
async function dailyDataQualityCheck(): Promise<void> {
  const partitions = await shardMappingService.getAllMappings();

  for (const shard of partitions) {
    for (const partitionKey of shard.partitionKeys) {
      const report = await checkPartitionDataQuality(partitionKey);

      if (report.quality_score < 98) {
        // Alert state admins
        await alerting.sendAlert({
          severity: 'high',
          title: `Data quality degraded for partition ${partitionKey}`,
          description: `Quality score: ${report.quality_score}% (threshold: 98%)`,
          details: report,
          recipients: [`${partitionKey.toLowerCase()}-admins@gainwell.com`],
        });
      }

      // Store report for trend analysis
      await dataWarehouse.insert('data_quality_reports', report);
    }
  }
}
