**Monthly SLO Review**:

```typescript
// Generate monthly SLO report per partition
async function generateMonthlySLOReport(
  partitionKey: string,
  year: number,
  month: number
): Promise<SLOReport> {
  // Query Prometheus for partition metrics
  const startDate = new Date(year, month - 1, 1);
  const endDate = new Date(year, month, 0, 23, 59, 59);

  const p95Latency = await prometheus.query(
    `histogram_quantile(0.95, rate(shard_query_duration_seconds_bucket{shard_id="${partitionKey}"}[30d]))`
  );

  const availability = await prometheus.query(
    `avg_over_time(up{shard_id="${partitionKey}"}[30d]) * 100`
  );

  const crossPartitionQueryRate = await prometheus.query(
    `rate(shard_query_duration_seconds_count{shard_id="${partitionKey}", query_type="cross_shard"}[30d])`
  );

  return {
    partition_key: partitionKey,
    month: `${year}-${month.toString().padStart(2, '0')}`,
    metrics: {
      p95_latency_ms: p95Latency * 1000,
      p95_latency_slo: 500,
      p95_latency_met: p95Latency * 1000 < 500,

      availability_percent: availability,
      availability_slo: 99.95,
      availability_met: availability >= 99.95,

      cross_partition_query_rate: crossPartitionQueryRate,
      cross_partition_query_rate_slo: 0.1,  // <10% of queries
      cross_partition_query_rate_met: crossPartitionQueryRate < 0.1,
    },
    slo_compliance: calculateSLOCompliance(metrics),
  };
}

// Send monthly report to state account managers
async function sendMonthlySLOReports(): Promise<void> {
  const year = new Date().getFullYear();
  const month = new Date().getMonth();  // Previous month

  const partitions = await shardMappingService.getAllMappings();

  for (const shard of partitions) {
    for (const partitionKey of shard.partitionKeys) {
      const report = await generateMonthlySLOReport(partitionKey, year, month);

      // Send to state account manager
      await email.send({
        to: `${partitionKey.toLowerCase()}-account-manager@gainwell.com`,
        subject: `${partitionKey} Partition - Monthly SLO Report (${year}-${month})`,
        body: renderSLOReport(report),
        attachments: [
          { filename: `${partitionKey}-slo-report.json`, content: JSON.stringify(report) },
        ],
      });
    }
  }
}
