├─ 480M claims (all 50 states)
├─ Size: 385TB
├─ Instance: 128 vCPU, 864GB RAM
├─ Performance:
   ├─ FL query P95 latency: 8.5 seconds (SLA: <3s) ❌
   ├─ FL write throughput: 2,500 TPS (peak: 3,800 TPS) ❌
   └─ Connection pool exhausted during peak
```

**After Partitioning** (Tenant-Based):

```text
Partitioned Architecture:
├─ FL Partition:
   ├─ 58M claims (FL only)
   ├─ Size: 41TB
   ├─ Instance: 16 vCPU, 128GB RAM
   ├─ Performance:
      ├─ Query P95 latency: 450ms ✓
      ├─ Write throughput: 2,800 TPS (headroom: 40%) ✓
      └─ Connection pool utilization: 45%

├─ CA Partition:
   ├─ 95M claims
   ├─ Instance: 32 vCPU, 256GB RAM

├─ Other partitions...
```

**Implementation**:

```typescript
// claims-service-florida.ts
// Florida-specific Claims Service implementation

import { ShardRouter, QueryContext } from './shard-router';

export class FloridaClaimsService {
  private readonly FLORIDA_STATE_CODE = 'FL';

  constructor(private shardRouter: ShardRouter) {}

  /**
   * Get claims for Florida member (single partition query)
   */
  async getClaimsByMember(memberId: string, dateRange?: DateRange): Promise<Claim[]> {
    const sql = `
      SELECT
        claim_id, member_id, service_date, provider_id,
        cpt_code, amount, status, adjudication_date
      FROM claims
      ORDER BY service_date DESC
      LIMIT 100
    `;

    const context: QueryContext = { partitionKey: this.FLORIDA_STATE_CODE };

    const startTime = Date.now();
    const claims = await this.shardRouter.query<Claim>(
      sql,
      [memberId, dateRange?.start || null, dateRange?.end || null],
      context
    );
    const duration = Date.now() - startTime;

    // Metrics
    this.recordMetric('claims_by_member_duration_ms', duration, {
      state: this.FLORIDA_STATE_CODE,
      result_count: claims.length,
    });

    return claims;
  }

  /**
   * Create claim (single partition transaction)
   */
  async createClaim(claim: ClaimInput): Promise<Claim> {
    // Validate state code
    if (claim.stateCode !== this.FLORIDA_STATE_CODE) {
      throw new Error(`Invalid state code for Florida partition: ${claim.stateCode}`);
    }

    return this.shardRouter.transaction(this.FLORIDA_STATE_CODE, async (client) => {
      // Insert claim
      const claimResult = await client.query(
        `INSERT INTO claims (
          member_id, state_code, service_date, provider_id,
          cpt_code, amount, status
        RETURNING *`,
        [
          claim.memberId,
          this.FLORIDA_STATE_CODE,
          claim.serviceDate,
          claim.providerId,
          claim.cptCode,
          claim.amount,
          'pending'
        ]
      );

      const newClaim = claimResult.rows[0];

      // Insert claim lines (same transaction, same partition)
      for (const line of claim.lines || []) {
        await client.query(
          `INSERT INTO claim_lines (
            claim_id, line_number, cpt_code, units, amount
          [newClaim.claim_id, line.lineNumber, line.cptCode, line.units, line.amount]
        );
      }

      // Publish event (claims created)
      await this.publishEvent({
        eventType: 'claim.created',
        claimId: newClaim.claim_id,
        stateCode: this.FLORIDA_STATE_CODE,
        memberId: claim.memberId,
        amount: claim.amount,
      });

      return newClaim;
    });
  }

  /**
   * Get Florida claims summary (single partition aggregation)
   */
  async getClaimsSummary(dateRange: DateRange): Promise<ClaimsSummary> {
    const sql = `
      SELECT
        COUNT(*) as total_claims,
        SUM(amount) as total_amount,
        AVG(amount) as avg_amount,
        COUNT(DISTINCT member_id) as unique_members,
        COUNT(DISTINCT provider_id) as unique_providers
      FROM claims
        AND status IN ('approved', 'paid')
    `;

    const context: QueryContext = { partitionKey: this.FLORIDA_STATE_CODE };
    const result = await this.shardRouter.query<any>(sql, [dateRange.start, dateRange.end], context);

    return {
      state_code: this.FLORIDA_STATE_CODE,
      total_claims: parseInt(result[0].total_claims),
      total_amount: parseFloat(result[0].total_amount),
      avg_amount: parseFloat(result[0].avg_amount),
      unique_members: parseInt(result[0].unique_members),
      unique_providers: parseInt(result[0].unique_providers),
    };
  }

  private recordMetric(metric: string, value: number, tags: Record<string, any>): void {
    // Send to Prometheus
    prometheusRegistry.histogram(metric).observe(value, tags);
  }

  private async publishEvent(event: any): Promise<void> {
    // Publish to Azure Service Bus
    await serviceBus.publish('claims-events', event);
  }
}
```

**Results**:

