US West Region: 680K providers (CA, OR, WA, NV, AZ, UT, ID, MT, WY, CO, NM)
US Central Region: 900K providers (ND, SD, NE, KS, OK, TX, MN, IA, MO, AR, LA, WI, IL, MI, IN, OH, KY, TN, MS, AL)
```

**Before Partitioning**:

```text
Single Provider Database (East US region):
├─ Users: Nationwide
├─ West Coast latency: 78ms network + 120ms query = 198ms
├─ East Coast latency: 8ms network + 120ms query = 128ms
├─ Midwest latency: 35ms network + 120ms query = 155ms
```

**After Geographic Partitioning**:

```text
Regional Partitions:
├─ US-East Partition (Azure East US):
   ├─ 820K providers
   ├─ East Coast users: 8ms + 120ms = 128ms (no change)

├─ US-West Partition (Azure West US):
   ├─ 680K providers
   ├─ West Coast users: 8ms + 120ms = 128ms (35% faster)

├─ US-Central Partition (Azure Central US):
   └─ 900K providers
   └─ Midwest users: 12ms + 120ms = 132ms (15% faster)
```

**Implementation**:

```typescript
// provider-service-geographic.ts
import { ShardRouter, QueryContext } from './shard-router';

export class GeographicProviderService {
  constructor(private shardRouter: ShardRouter) {}

  /**
   * Search providers by location (single region query)
   */
  async searchProviders(criteria: ProviderSearchCriteria): Promise<Provider[]> {
    // Determine region from search location
    const region = this.determineRegion(criteria.state || criteria.zipCode);

    const sql = `
      SELECT
        provider_id, npi, first_name, last_name, specialty,
        address, city, state, zip_code, phone,
        ST_Distance(
          location::geography,
        ) / 1609.34 as distance_miles
      FROM providers
        AND ST_DWithin(
          location::geography,
        )
      ORDER BY distance_miles
    `;

    const context: QueryContext = { partitionKey: region };

    return this.shardRouter.query<Provider>(
      sql,
      [
        criteria.longitude,
        criteria.latitude,
        criteria.specialty || null,
        criteria.state || null,
        criteria.radiusMiles || 25,
        criteria.limit || 50,
      ],
      context
    );
  }

  /**
   * Get provider by ID (may require cross-region query if region unknown)
   */
  async getProviderById(providerId: string, region?: string): Promise<Provider | null> {
    if (region) {
      // Region known - single partition query
      const context: QueryContext = { partitionKey: region };
      const result = await this.shardRouter.query<Provider>(
        [providerId],
        context
      );
      return result[0] || null;
    } else {
      // Region unknown - query all regions (fan-out)
      const context: QueryContext = { allPartitions: true };
      const results = await this.shardRouter.query<Provider>(
        [providerId],
        context
      );

      // Provider should exist in exactly one partition
      if (results.length > 1) {
        this.logger.warn('Provider found in multiple partitions', {
          provider_id: providerId,
          count: results.length
        });
      }

      return results[0] || null;
    }
  }

  /**
   * Determine region from state code or zip code
   */
  private determineRegion(location: string): string {
    const eastStates = ['VT', 'NH', 'ME', 'MA', 'RI', 'CT', 'NY', 'NJ', 'PA', 'DE', 'MD', 'VA', 'WV', 'NC', 'SC', 'GA', 'FL'];
    const westStates = ['CA', 'OR', 'WA', 'NV', 'AZ', 'UT', 'ID', 'MT', 'WY', 'CO', 'NM'];
    const centralStates = ['ND', 'SD', 'NE', 'KS', 'OK', 'TX', 'MN', 'IA', 'MO', 'AR', 'LA', 'WI', 'IL', 'MI', 'IN', 'OH', 'KY', 'TN', 'MS', 'AL'];

    // If location is state code
    if (location.length === 2) {
      if (eastStates.includes(location)) return 'US_EAST';
      if (westStates.includes(location)) return 'US_WEST';
      if (centralStates.includes(location)) return 'US_CENTRAL';
    }

    // If location is zip code, map to region (simplified)
    const zipCode = parseInt(location);
    if (zipCode >= 0 && zipCode < 20000) return 'US_EAST';
    if (zipCode >= 80000 && zipCode < 100000) return 'US_WEST';
    return 'US_CENTRAL';
  }

  /**
   * Cross-region analytics query (all providers by specialty)
   */
  async getProviderCountBySpecialty(): Promise<Record<string, number>> {
    const sql = `
      SELECT specialty, COUNT(*) as count
      FROM providers
      WHERE specialty IS NOT NULL
      GROUP BY specialty
      ORDER BY count DESC
    `;

    const context: QueryContext = { allPartitions: true };
    const results = await this.shardRouter.query<{specialty: string, count: string}>(sql, [], context);

    // Aggregate counts from all regions
    const aggregated: Record<string, number> = {};
    for (const row of results) {
      aggregated[row.specialty] = (aggregated[row.specialty] || 0) + parseInt(row.count);
    }

    return aggregated;
  }
}
```

**Client-Side Routing** (React):

```typescript
