-- Automated partition management
CREATE OR REPLACE FUNCTION manage_audit_log_partitions()
RETURNS void AS $$
DECLARE
    current_month DATE;
    next_month DATE;
    partition_name TEXT;
    old_partition_name TEXT;
    retention_cutoff DATE;
BEGIN
    -- Create next month's partition (run monthly)
    current_month := DATE_TRUNC('month', CURRENT_DATE);
    next_month := current_month + INTERVAL '1 month';
    partition_name := 'audit_logs_' || TO_CHAR(next_month, 'YYYY_MM');

    EXECUTE format(
        'CREATE TABLE IF NOT EXISTS %I PARTITION OF audit_logs FOR VALUES FROM (%L) TO (%L)',
        partition_name,
        TO_CHAR(next_month, 'YYYY-MM-DD'),
        TO_CHAR(next_month + INTERVAL '1 month', 'YYYY-MM-DD')
    );

    -- Create indexes on new partition
    EXECUTE format('CREATE INDEX IF NOT EXISTS idx_%I_user ON %I(user_id)', partition_name, partition_name);
    EXECUTE format('CREATE INDEX IF NOT EXISTS idx_%I_resource ON %I(resource_type, resource_id)', partition_name, partition_name);
    EXECUTE format('CREATE INDEX IF NOT EXISTS idx_%I_state ON %I(state_code)', partition_name, partition_name);

    RAISE NOTICE 'Created partition: %', partition_name;

    -- Drop partitions older than 3 years (retention policy)
    retention_cutoff := current_month - INTERVAL '3 years';
    old_partition_name := 'audit_logs_' || TO_CHAR(retention_cutoff, 'YYYY_MM');

    EXECUTE format('DROP TABLE IF EXISTS %I', old_partition_name);
    RAISE NOTICE 'Dropped old partition: %', old_partition_name;
END;
$$ LANGUAGE plpgsql;

-- Schedule monthly (via cron or application scheduler)
SELECT manage_audit_log_partitions();
