// audit-service.ts
import { Pool } from 'pg';

export class AuditService {
  constructor(private db: Pool) {}

  /**
   * Query recent audit logs (single partition, fast)
   */
  async getRecentAuditLogs(userId: string, hours: number = 24): Promise<AuditLog[]> {
    const sql = `
      SELECT *
      FROM audit_logs
        AND event_timestamp >= NOW() - INTERVAL '${hours} hours'
      ORDER BY event_timestamp DESC
      LIMIT 1000
    `;

    // PostgreSQL automatically routes to current month partition
    const result = await this.db.query(sql, [userId]);
    return result.rows;
  }

  /**
   * Query historical audit logs (spans multiple partitions)
   */
  async getAuditLogsByDateRange(
    userId: string,
    startDate: Date,
    endDate: Date
  ): Promise<AuditLog[]> {
    const sql = `
      SELECT *
      FROM audit_logs
      ORDER BY event_timestamp DESC
      LIMIT 10000
    `;

    // PostgreSQL automatically queries relevant partitions
    // (partition pruning based on date range)
    const result = await this.db.query(sql, [userId, startDate, endDate]);
    return result.rows;
  }

  /**
   * Generate HIPAA audit report (cross-partition aggregation)
   */
  async generateHIPAAReport(
    stateCode: string,
    month: string  // Format: 'YYYY-MM'
  ): Promise<HIPAAReport> {
    const [year, monthNum] = month.split('-');
    const startDate = new Date(parseInt(year), parseInt(monthNum) - 1, 1);
    const endDate = new Date(parseInt(year), parseInt(monthNum), 0);

    // Query single partition (specific month)
    const sql = `
      SELECT
        COUNT(*) as total_accesses,
        COUNT(DISTINCT user_id) as unique_users,
        COUNT(DISTINCT session_id) as unique_sessions,
        action,
        resource_type,
        COUNT(*) as count_by_type
      FROM audit_logs
      GROUP BY action, resource_type
      ORDER BY count_by_type DESC
    `;

    const result = await this.db.query(sql, [stateCode, startDate, endDate]);

    return {
      state_code: stateCode,
      month,
      total_accesses: result.rows.reduce((sum, r) => sum + parseInt(r.count_by_type), 0),
      unique_users: parseInt(result.rows[0]?.unique_users || '0'),
      unique_sessions: parseInt(result.rows[0]?.unique_sessions || '0'),
      by_action: this.groupByAction(result.rows),
      by_resource_type: this.groupByResourceType(result.rows),
    };
  }

  /**
   * Efficient data deletion (drop entire partition vs. DELETE rows)
   */
  async archiveOldAuditLogs(): Promise<void> {
    // Dropping partition is instant (vs. hours to DELETE millions of rows)
    const retentionCutoff = new Date();
    retentionCutoff.setFullYear(retentionCutoff.getFullYear() - 3);

    const partitionName = `audit_logs_${retentionCutoff.getFullYear()}_${(retentionCutoff.getMonth() + 1).toString().padStart(2, '0')}`;

    await this.db.query(`DROP TABLE IF EXISTS ${partitionName}`);

    this.logger.info('Archived audit logs', {
      partition: partitionName,
      cutoff_date: retentionCutoff,
    });
  }
}
